window.QUIZ_BANK = [{"id": 1, "question": "What is a program?", "options": ["Executable code", "A computer screen", "A keyboard", "A printer"], "answer": 0, "topic": "Foundations", "explanation": "A program is executable code: instructions that perform a task. A script is a program; a monitor or keyboard is hardware."}, {"id": 2, "question": "Which is an example of a program?", "options": ["A script that adds two numbers", "A monitor", "A mouse", "A desk"], "answer": 0, "topic": "Foundations", "explanation": "A program is executable code: instructions that perform a task. A script is a program; a monitor or keyboard is hardware."}, {"id": 3, "question": "What is included in software?", "options": ["Code only", "Code and hardware", "Code, libraries, and documentation", "Hardware and documents"], "answer": 2, "topic": "Foundations", "explanation": "Software includes code, libraries and documentation. In this question bank, a software product is software made to meet a specific requirement."}, {"id": 4, "question": "A software product is made for:", "options": ["A specific requirement", "Any random task", "Hardware testing", "Coding practice"], "answer": 0, "topic": "Foundations", "explanation": "Software includes code, libraries and documentation. In this question bank, a software product is software made to meet a specific requirement."}, {"id": 5, "question": "What is the purpose of a software product?", "options": ["To solve users' needs", "To damage a computer", "To replace electricity", "To store only pictures"], "answer": 0, "topic": "Foundations", "explanation": "Software includes code, libraries and documentation. In this question bank, a software product is software made to meet a specific requirement."}, {"id": 6, "question": "What is the fundamental difference between a program and a software product?", "options": ["A program includes documentation; software does not", "Software product includes code, libraries, and documentation for a specific requirement", "A program is designed for commercial sales only", "There is no difference between them"], "answer": 1, "topic": "Foundations", "explanation": "Software includes code, libraries and documentation. In this question bank, a software product is software made to meet a specific requirement."}, {"id": 7, "question": "A payroll script contains executable statements, but no accompanying libraries or documentation. Under the syllabus terminology, the most precise classification is:", "options": ["A complete software product, because it performs a useful task", "A program, because only executable code is specified", "Software, because every executable file is software in the broad sense", "A software product, because its purpose is specific"], "answer": 1, "topic": "Foundations", "explanation": "Software includes code, libraries and documentation. In this question bank, a software product is software made to meet a specific requirement."}, {"id": 8, "question": "A word processor is supplied with executable code, libraries, user help pages and developer documentation. Which distinction is best supported?", "options": ["It is software, while it becomes a software product only when made for a specific requirement", "It is merely a program because users interact with executable code", "It is a software product only if all documentation is embedded in the executable", "It is not software unless it includes source code"], "answer": 0, "topic": "Foundations", "explanation": "Software includes code, libraries and documentation. In this question bank, a software product is software made to meet a specific requirement."}, {"id": 9, "question": "A team delivers a custom payroll system for one company. Which fact most directly makes it a software product in the syllabus sense?", "options": ["It has more than one executable module", "It is written using a high-level programming language", "It has been made for a specific requirement", "It is accompanied by a user manual"], "answer": 2, "topic": "Foundations", "explanation": "Software includes code, libraries and documentation. In this question bank, a software product is software made to meet a specific requirement."}, {"id": 10, "question": "Who uses manuals to learn software?", "options": ["Users", "Only printers", "Only routers", "Only servers"], "answer": 0, "topic": "Foundations", "explanation": "Documentation helps users operate the software and helps developers and maintainers understand and change it safely."}, {"id": 11, "question": "Why is documentation considered a mandatory component of software?", "options": ["It is required for sales tax exemption", "Users, developers, and maintainers depend on it to operate and change the code", "It replaces unit testing during execution", "It makes the executable file run faster"], "answer": 1, "topic": "Foundations", "explanation": "Documentation helps users operate the software and helps developers and maintainers understand and change it safely."}, {"id": 12, "question": "Documentation helps maintainers:", "options": ["Change software later more safely", "Avoid all testing", "Remove developers", "Prevent software use"], "answer": 0, "topic": "Foundations", "explanation": "Documentation helps users operate the software and helps developers and maintainers understand and change it safely."}, {"id": 13, "question": "Documentation is part of software, not an extra. True or false?", "options": ["True", "False", "Optional always", "Only for users"], "answer": 0, "topic": "Foundations", "explanation": "Documentation helps users operate the software and helps developers and maintainers understand and change it safely."}, {"id": 14, "question": "A maintainer must alter a calculation six months after release. The original developer has left, and no design or requirement documents exist. Which syllabus argument is most directly illustrated?", "options": ["Documentation is primarily a legal formality", "Documentation is needed only during requirements gathering", "Maintenance becomes slow and risky when supporting documents are absent", "Executable code is not part of software"], "answer": 2, "topic": "Foundations", "explanation": "Documentation helps users operate the software and helps developers and maintainers understand and change it safely."}, {"id": 15, "question": "Software engineering according to IEEE is mainly:", "options": ["Coding quickly without rules", "A systematic, disciplined, quantifiable approach", "Only use of modern languages", "Hardware development"], "answer": 1, "topic": "Foundations", "explanation": "Software engineering applies engineering principles through a systematic, disciplined and quantifiable approach to developing and maintaining software."}, {"id": 16, "question": "Which organization gives a definition of software engineering in the notes?", "options": ["IEEE", "FIFA", "WHO", "NASA"], "answer": 0, "topic": "Foundations", "explanation": "Software engineering applies engineering principles through a systematic, disciplined and quantifiable approach to developing and maintaining software."}, {"id": 17, "question": "According to IEEE, software engineering is an engineering approach to software development and maintenance.", "options": ["True", "False", "Only for hardware", "None of these"], "answer": 0, "topic": "Foundations", "explanation": "Software engineering applies engineering principles through a systematic, disciplined and quantifiable approach to developing and maintaining software."}, {"id": 18, "question": "Software engineering uses scientific principles and what?", "options": ["Guesswork", "Methods", "Random choices", "Luck"], "answer": 1, "topic": "Foundations", "explanation": "Software engineering applies engineering principles through a systematic, disciplined and quantifiable approach to developing and maintaining software."}, {"id": 19, "question": "Software engineering uses:", "options": ["Engineering principles", "Cooking principles", "Painting rules", "Driving rules"], "answer": 0, "topic": "Foundations", "explanation": "Software engineering applies engineering principles through a systematic, disciplined and quantifiable approach to developing and maintaining software."}, {"id": 20, "question": "What is the main goal of software engineering?", "options": ["Write code quickly", "Develop reliable software", "Avoid documentation", "Reduce programming languages"], "answer": 1, "topic": "Foundations", "explanation": "Software engineering applies engineering principles through a systematic, disciplined and quantifiable approach to developing and maintaining software."}, {"id": 21, "question": "Systematic means:", "options": ["Random", "Planned and ordered", "Unclear", "Uncontrolled"], "answer": 1, "topic": "Foundations", "explanation": "Systematic means planned and ordered work. Experience alone does not establish an organized process."}, {"id": 22, "question": "A project manager says a process is systematic because every engineer is experienced. Which response best reflects the syllabus definition?", "options": ["Experience alone establishes a systematic process", "Systematic means work follows a planned order rather than ad hoc effort", "Systematic means all work is performed by one engineer", "Systematic means project cost is fixed before requirements are gathered"], "answer": 1, "topic": "Foundations", "explanation": "Systematic means planned and ordered work. Experience alone does not establish an organized process."}, {"id": 23, "question": "What does disciplined mean?", "options": ["Following rules and standards", "Ignoring instructions", "Working randomly", "Avoiding teamwork"], "answer": 0, "topic": "Foundations", "explanation": "Disciplined work follows agreed procedures, rules and standards consistently."}, {"id": 24, "question": "What does \"quantifiable\" mean?", "options": ["Work is measurable", "Work is random", "Work is simple", "Work is informal"], "answer": 0, "topic": "Foundations", "explanation": "Quantifiable means measurable. A sound process uses a planned method, agreed procedures and measurements of progress, cost or quality."}, {"id": 25, "question": "A team uses a documented process consistently, but reports progress only as 'nearly finished' and quality as 'good'. Which IEEE element is weakest?", "options": ["Systematic", "Disciplined", "Quantifiable", "Operational"], "answer": 2, "topic": "Foundations", "explanation": "Quantifiable means measurable. A sound process uses a planned method, agreed procedures and measurements of progress, cost or quality."}, {"id": 26, "question": "Which project practice most closely satisfies all three defining terms in the IEEE description of software engineering?", "options": ["Developers improvise, then estimate quality from customer reactions", "A team follows a planned method, applies agreed procedures, and measures cost and progress", "A team follows a fixed schedule but does not measure product quality", "A team measures output size while allowing each member to choose an unrelated process"], "answer": 1, "topic": "Foundations", "explanation": "Quantifiable means measurable. A sound process uses a planned method, agreed procedures and measurements of progress, cost or quality."}, {"id": 27, "question": "As large software grows, its complexity generally does what?", "options": ["Disappears", "Increases", "Stays zero", "Becomes irrelevant"], "answer": 1, "topic": "Foundations", "explanation": "As functions and components increase, the interactions between them multiply. Complexity can therefore grow faster than program size."}, {"id": 28, "question": "Large programs need software engineering mainly because complexity grows how?", "options": ["Linearly", "Not at all", "Faster than size", "Only with money"], "answer": 2, "topic": "Foundations", "explanation": "As functions and components increase, the interactions between them multiply. Complexity can therefore grow faster than program size."}, {"id": 29, "question": "Why does software complexity increase?", "options": ["More interactions", "Less documentation", "Fewer functions", "Smaller programs"], "answer": 0, "topic": "Foundations", "explanation": "As functions and components increase, the interactions between them multiply. Complexity can therefore grow faster than program size."}, {"id": 30, "question": "What does abstraction do?", "options": ["Adds more details", "Hides irrelevant details", "Removes all functions", "Increases complexity"], "answer": 1, "topic": "Foundations", "explanation": "Abstraction focuses on the details relevant at the current level. Postponed details are introduced again at lower levels; they are not deleted permanently."}, {"id": 31, "question": "Which technique reduces complexity by omitting irrelevant details to focus on relevant aspects first?", "options": ["Decomposition", "Abstraction", "Integration", "Refactoring"], "answer": 1, "topic": "Foundations", "explanation": "Abstraction focuses on the details relevant at the current level. Postponed details are introduced again at lower levels; they are not deleted permanently."}, {"id": 32, "question": "Abstraction means temporarily ignoring some details. What happens to those details later?", "options": ["They are deleted forever", "They are restored at lower levels", "They are sold", "They are encrypted"], "answer": 1, "topic": "Foundations", "explanation": "Abstraction focuses on the details relevant at the current level. Postponed details are introduced again at lower levels; they are not deleted permanently."}, {"id": 33, "question": "A library-system designer initially models only books, members and borrowing, postponing fines and reports. Which technique is being applied?", "options": ["Decomposition, because the system is divided into independent teams", "Abstraction, because irrelevant details are temporarily omitted for the current purpose", "Modularity, because every feature is implemented as a separate executable", "Interoperability, because the model ignores external systems"], "answer": 1, "topic": "Foundations", "explanation": "Abstraction focuses on the details relevant at the current level. Postponed details are introduced again at lower levels; they are not deleted permanently."}, {"id": 34, "question": "Decomposition means:", "options": ["Combining everything", "Dividing a complex problem into smaller parts", "Deleting a project", "Writing documentation only"], "answer": 1, "topic": "Foundations", "explanation": "Decomposition breaks a large problem into smaller parts. Good parts can be solved independently and communicate through limited, clear interfaces."}, {"id": 35, "question": "Dividing a complex problem into smaller independent sub-problems is known as:", "options": ["Abstraction", "Decomposition", "Encapsulation", "Inheritance"], "answer": 1, "topic": "Foundations", "explanation": "Decomposition breaks a large problem into smaller parts. Good parts can be solved independently and communicate through limited, clear interfaces."}, {"id": 36, "question": "Good decomposition should:", "options": ["Make components highly dependent", "Minimize interactions among components", "Put all features in one component", "Avoid independent testing"], "answer": 1, "topic": "Foundations", "explanation": "Decomposition breaks a large problem into smaller parts. Good parts can be solved independently and communicate through limited, clear interfaces."}, {"id": 37, "question": "Good decomposition creates:", "options": ["Independent components", "More confusion", "Larger problems", "More hardware"], "answer": 0, "topic": "Foundations", "explanation": "Decomposition breaks a large problem into smaller parts. Good parts can be solved independently and communicate through limited, clear interfaces."}, {"id": 38, "question": "An online shop is divided into catalog, cart, payment and order-tracking components. The components can be built independently and communicate through limited interfaces. What makes this a good decomposition?", "options": ["Every component manipulates every other component's internal data", "The split is based only on the number of lines of code", "Components are independently solvable and their interactions are minimised", "The system avoids combining component solutions"], "answer": 2, "topic": "Foundations", "explanation": "Decomposition breaks a large problem into smaller parts. Good parts can be solved independently and communicate through limited, clear interfaces."}, {"id": 39, "question": "A system is split into modules, but each module continuously reads and changes the internal data of all the others. Which conclusion follows from the notes?", "options": ["The decomposition has reduced complexity because module count increased", "The decomposition is poor because close interrelationships prevent independent problem solving", "The design is necessarily an example of abstraction", "The modules automatically become reusable"], "answer": 1, "topic": "Foundations", "explanation": "Decomposition breaks a large problem into smaller parts. Good parts can be solved independently and communicate through limited, clear interfaces."}, {"id": 40, "question": "Why is software engineering needed for large software?", "options": ["To manage complexity", "To remove users", "To avoid testing", "To stop updates"], "answer": 0, "topic": "Foundations", "explanation": "Software engineering helps manage complexity, development cost, changing requirements and the difficulty of expanding a system economically."}, {"id": 41, "question": "Why is software engineering needed?", "options": ["To develop reliable and scalable software", "To make software more confusing", "To avoid planning", "To remove testing"], "answer": 0, "topic": "Foundations", "explanation": "Software engineering helps manage complexity, development cost, changing requirements and the difficulty of expanding a system economically."}, {"id": 42, "question": "One reason software engineering is needed is the dynamic nature of what?", "options": ["Hardware prices", "User requirements and environment", "Coffee machines", "Office chairs"], "answer": 1, "topic": "Foundations", "explanation": "Software engineering helps manage complexity, development cost, changing requirements and the difficulty of expanding a system economically."}, {"id": 43, "question": "A product must repeatedly change because the user's environment and needs evolve. Which stated reason for software engineering is most directly relevant?", "options": ["Dynamic nature", "Budget", "Portability", "Alpha testing"], "answer": 0, "topic": "Foundations", "explanation": "Software engineering helps manage complexity, development cost, changing requirements and the difficulty of expanding a system economically."}, {"id": 44, "question": "One reason we need software engineering is to manage the cost of what?", "options": ["Hardware only", "Software development", "Office rent", "Coffee"], "answer": 1, "topic": "Foundations", "explanation": "Software engineering helps manage complexity, development cost, changing requirements and the difficulty of expanding a system economically."}, {"id": 45, "question": "Hardware costs fall through mass manufacturing, yet software remains expensive when developed without a proper process. Which syllabus reason does this illustrate?", "options": ["Dynamic nature", "Cost", "Safety", "Interoperability"], "answer": 1, "topic": "Foundations", "explanation": "Software engineering helps manage complexity, development cost, changing requirements and the difficulty of expanding a system economically."}, {"id": 46, "question": "A company can build a small application, but cannot expand it economically as users and features grow. Which need for software engineering is most directly involved?", "options": ["Scalability", "Portability", "Acceptance testing", "Quantifiability"], "answer": 0, "topic": "Foundations", "explanation": "Software engineering helps manage complexity, development cost, changing requirements and the difficulty of expanding a system economically."}, {"id": 47, "question": "Scalability means software can do what?", "options": ["Handle growth", "Only run once", "Never change", "Avoid users"], "answer": 0, "topic": "Software quality", "explanation": "Scalability is the ability to handle growth in users, load or functionality."}, {"id": 48, "question": "Usability means software is easy to what?", "options": ["Learn and use", "Delete", "Hide", "Break"], "answer": 0, "topic": "Software quality", "explanation": "Usability concerns how easily users learn and operate the software."}, {"id": 49, "question": "Security protects software from what?", "options": ["Unauthorized access", "Good documentation", "Regular updates", "Approved users"], "answer": 0, "topic": "Software quality", "explanation": "Security protects software and information against unauthorized access and attacks."}, {"id": 50, "question": "Portability means software can:", "options": ["Run on different environments", "Never be moved", "Only run once", "Avoid testing"], "answer": 0, "topic": "Software quality", "explanation": "Portability concerns moving software to another operating system or environment."}, {"id": 51, "question": "A product works correctly but cannot be moved from one operating system to another. Which characteristic is missing?", "options": ["Interoperability", "Portability", "Maintainability", "Dependability"], "answer": 1, "topic": "Software quality", "explanation": "Portability concerns moving software to another operating system or environment."}, {"id": 52, "question": "Reusability means software parts can be what?", "options": ["Used again", "Thrown away always", "Never changed", "Only printed"], "answer": 0, "topic": "Software quality", "explanation": "Reusability means an existing software component can be used in another application."}, {"id": 53, "question": "A software component can be used again in another application. This is best classified as:", "options": ["Adaptability", "Reusability", "Safety", "Correctness"], "answer": 1, "topic": "Software quality", "explanation": "Reusability means an existing software component can be used in another application."}, {"id": 54, "question": "Which characteristic means software is easy to correct and improve?", "options": ["Maintainability", "Safety", "Portability", "Functionality"], "answer": 0, "topic": "Software quality", "explanation": "Maintainability concerns how easily software can be corrected, updated or improved."}, {"id": 55, "question": "Which quality means working with other systems?", "options": ["Interoperability", "Maintainability", "Efficiency", "Modularity"], "answer": 0, "topic": "Software quality", "explanation": "Interoperability is the ability of independently developed systems to exchange information and work together."}, {"id": 56, "question": "A system exchanges data and works together with another independently developed system. Which transitional characteristic is demonstrated?", "options": ["Modularity", "Interoperability", "Maintainability", "Correctness"], "answer": 1, "topic": "Software quality", "explanation": "Interoperability is the ability of independently developed systems to exchange information and work together."}, {"id": 57, "question": "Modularity means software is divided into:", "options": ["Modules", "Cables", "Computers", "Networks"], "answer": 0, "topic": "Software quality", "explanation": "Modularity separates the system into defined components, making individual parts easier to understand and change."}, {"id": 58, "question": "A system's internal parts are separately defined, making it easier to modify one part without redesigning the whole. Which maintenance characteristic is most directly described?", "options": ["Modularity", "Portability", "Budget", "Dependability"], "answer": 0, "topic": "Software quality", "explanation": "Modularity separates the system into defined components, making individual parts easier to understand and change."}, {"id": 59, "question": "Which characteristic means software can be relied upon to work?", "options": ["Portability", "Dependability", "Flexibility", "Reusability"], "answer": 1, "topic": "Software quality", "explanation": "Dependability means the system can be relied on to perform its intended work."}, {"id": 60, "question": "A system continues to function reliably, but its failure could cause harm to people. Which operational characteristic is specifically concerned with avoiding harm when failure occurs?", "options": ["Security", "Usability", "Safety", "Efficiency"], "answer": 2, "topic": "Software quality", "explanation": "Safety concerns avoiding harm to people or the environment, including when a system fails. Reliable operation alone does not guarantee safety."}, {"id": 61, "question": "Which is a good software quality?", "options": ["Poor usability", "Low security", "Maintainability", "High complexity"], "answer": 2, "topic": "Software quality", "explanation": "In this bank, operational characteristics describe how well software works; transitional characteristics describe movement between environments; maintenance characteristics describe its ability to survive change."}, {"id": 62, "question": "Which is a good software characteristic?", "options": ["Usability", "Confusion", "Unreliability", "Complexity only"], "answer": 0, "topic": "Software quality", "explanation": "In this bank, operational characteristics describe how well software works; transitional characteristics describe movement between environments; maintenance characteristics describe its ability to survive change."}, {"id": 63, "question": "Operational characteristics answer which question?", "options": ["How well does it work while running?", "How easy is it to move?", "How easy is it to change?", "How much does it cost?"], "answer": 0, "topic": "Software quality", "explanation": "In this bank, operational characteristics describe how well software works; transitional characteristics describe movement between environments; maintenance characteristics describe its ability to survive change."}, {"id": 64, "question": "Which is an operational software characteristic?", "options": ["Reusability", "Portability", "Usability", "Adaptability"], "answer": 2, "topic": "Software quality", "explanation": "In this bank, operational characteristics describe how well software works; transitional characteristics describe movement between environments; maintenance characteristics describe its ability to survive change."}, {"id": 65, "question": "Usability and security are examples of which kind of characteristics?", "options": ["Operational", "Transitional", "Maintenance", "Financial"], "answer": 0, "topic": "Software quality", "explanation": "In this bank, operational characteristics describe how well software works; transitional characteristics describe movement between environments; maintenance characteristics describe its ability to survive change."}, {"id": 66, "question": "Under which group of good software characteristics do Portability and Reusability fall?", "options": ["Operational Characteristics", "Transitional Characteristics", "Maintenance Characteristics", "Security Characteristics"], "answer": 1, "topic": "Software quality", "explanation": "In this bank, operational characteristics describe how well software works; transitional characteristics describe movement between environments; maintenance characteristics describe its ability to survive change."}, {"id": 67, "question": "Modularity and Scalability belong to which category of software characteristics?", "options": ["Operational", "Maintenance", "Transitional", "Financial"], "answer": 1, "topic": "Software quality", "explanation": "In this bank, operational characteristics describe how well software works; transitional characteristics describe movement between environments; maintenance characteristics describe its ability to survive change."}, {"id": 68, "question": "Which pairing correctly matches the three groups of good-software characteristics with their central questions?", "options": ["Operational: survival under change; Transitional: resource use; Maintenance: movement between platforms", "Operational: how well it works; Transitional: how well it moves to another platform; Maintenance: how well it survives a changing environment", "Operational: ease of modification; Transitional: security; Maintenance: user learning", "Operational: reusability; Transitional: correctness; Maintenance: budget"], "answer": 1, "topic": "Software quality", "explanation": "In this bank, operational characteristics describe how well software works; transitional characteristics describe movement between environments; maintenance characteristics describe its ability to survive change."}, {"id": 69, "question": "What does SDLC stand for?", "options": ["Software Development Life Cycle", "System Data Link Code", "Software Design Logic Chart", "Simple Digital Life Code"], "answer": 0, "topic": "SDLC essentials", "explanation": "SDLC means Software Development Life Cycle. It organizes development activities and deliverables so teams can coordinate work predictably."}, {"id": 70, "question": "What is the main purpose of SDLC?", "options": ["Organize development", "Avoid testing", "Remove planning", "Increase coding errors"], "answer": 0, "topic": "SDLC essentials", "explanation": "SDLC means Software Development Life Cycle. It organizes development activities and deliverables so teams can coordinate work predictably."}, {"id": 71, "question": "How many SDLC stages are shown in these notes?", "options": ["Four", "Five", "Seven", "Ten"], "answer": 2, "topic": "SDLC essentials", "explanation": "SDLC means Software Development Life Cycle. It organizes development activities and deliverables so teams can coordinate work predictably."}, {"id": 72, "question": "What does a life-cycle model mainly show?", "options": ["The order of activities from start to end", "Only the coding style", "Only the team size", "Only the budget"], "answer": 0, "topic": "SDLC essentials", "explanation": "SDLC means Software Development Life Cycle. It organizes development activities and deliverables so teams can coordinate work predictably."}, {"id": 73, "question": "A team begins implementation before agreeing on what the customer needs. Different members choose different priorities, and their outputs do not fit together. Which SDLC benefit has been neglected most directly?", "options": ["A clear, organised framework that connects technical work to documented requirements", "The ability to eliminate all maintenance after release", "The ability to avoid stakeholder involvement", "A guarantee that no requirement will change"], "answer": 0, "topic": "SDLC essentials", "explanation": "SDLC means Software Development Life Cycle. It organizes development activities and deliverables so teams can coordinate work predictably."}, {"id": 74, "question": "What are entry criteria?", "options": ["Conditions before a phase starts", "Conditions after release", "Testing results", "Project costs"], "answer": 0, "topic": "SDLC essentials", "explanation": "Entry criteria must be satisfied before a phase begins. Exit criteria must be satisfied before it is considered complete. These conditions make progress observable."}, {"id": 75, "question": "What are exit criteria?", "options": ["Conditions to start coding", "Conditions to finish a phase", "User complaints", "Project deadlines"], "answer": 1, "topic": "SDLC essentials", "explanation": "Entry criteria must be satisfied before a phase begins. Exit criteria must be satisfied before it is considered complete. These conditions make progress observable."}, {"id": 76, "question": "Without entry and exit criteria, managers cannot easily monitor what?", "options": ["Progress", "Lunch time", "Weather", "Holidays"], "answer": 0, "topic": "SDLC essentials", "explanation": "Entry criteria must be satisfied before a phase begins. Exit criteria must be satisfied before it is considered complete. These conditions make progress observable."}, {"id": 77, "question": "A design phase is about to begin. According to the entry/exit criteria example, what should already be true?", "options": ["All modules must have passed integration testing", "The SRS must have been approved", "The live application must have passed smoke testing", "The maintenance team must have released a patch"], "answer": 1, "topic": "SDLC essentials", "explanation": "Entry criteria must be satisfied before a phase begins. Exit criteria must be satisfied before it is considered complete. These conditions make progress observable."}, {"id": 78, "question": "A development phase is considered complete only after all modules pass unit tests, before integration starts. This condition is an example of:", "options": ["An entry criterion for requirements gathering", "An exit criterion for development or unit-level work", "A deployment output", "A risk quadrant"], "answer": 1, "topic": "SDLC essentials", "explanation": "Entry criteria must be satisfied before a phase begins. Exit criteria must be satisfied before it is considered complete. These conditions make progress observable."}, {"id": 79, "question": "What is the first SDLC stage in these notes?", "options": ["Testing", "Deployment", "Planning and feasibility", "Maintenance"], "answer": 2, "topic": "Planning & requirements", "explanation": "Planning is the first stage in these notes. Feasibility evaluates technical, financial and operational viability, leading to a project plan and feasibility report."}, {"id": 80, "question": "Planning checks if a project is technically and financially what?", "options": ["Feasible", "Colorful", "Portable", "Printed"], "answer": 0, "topic": "Planning & requirements", "explanation": "Planning is the first stage in these notes. Feasibility evaluates technical, financial and operational viability, leading to a project plan and feasibility report."}, {"id": 81, "question": "The feasibility study asks: is the product worth building? True or false?", "options": ["False", "Only about colours", "True", "Only about team size"], "answer": 2, "topic": "Planning & requirements", "explanation": "Planning is the first stage in these notes. Feasibility evaluates technical, financial and operational viability, leading to a project plan and feasibility report."}, {"id": 82, "question": "Which stage checks project feasibility?", "options": ["Coding", "Planning", "Testing", "Maintenance"], "answer": 1, "topic": "Planning & requirements", "explanation": "Planning is the first stage in these notes. Feasibility evaluates technical, financial and operational viability, leading to a project plan and feasibility report."}, {"id": 83, "question": "During feasibility analysis, a proposed project is found technically possible but financially unaffordable and operationally unsuitable. What is the most appropriate decision implied by the notes?", "options": ["Proceed to coding because technical feasibility is sufficient", "Stop the project at this stage rather than discover the problem months later", "Prepare the SRS and defer the decision until testing", "Deploy a prototype to production"], "answer": 1, "topic": "Planning & requirements", "explanation": "Planning is the first stage in these notes. Feasibility evaluates technical, financial and operational viability, leading to a project plan and feasibility report."}, {"id": 84, "question": "What is a main output of planning?", "options": ["Feasibility report", "Live application", "Source code", "Test results only"], "answer": 0, "topic": "Planning & requirements", "explanation": "Planning is the first stage in these notes. Feasibility evaluates technical, financial and operational viability, leading to a project plan and feasibility report."}, {"id": 85, "question": "Which stage of the SDLC produces the project plan and feasibility report?", "options": ["Requirement Specification", "Planning and Feasibility Analysis", "System Design", "Deployment"], "answer": 1, "topic": "Planning & requirements", "explanation": "Planning is the first stage in these notes. Feasibility evaluates technical, financial and operational viability, leading to a project plan and feasibility report."}, {"id": 86, "question": "Which is a planning-stage activity?", "options": ["Cost estimation", "User acceptance testing", "Post-release bug fixing", "Source coding"], "answer": 0, "topic": "Planning & requirements", "explanation": "Planning is the first stage in these notes. Feasibility evaluates technical, financial and operational viability, leading to a project plan and feasibility report."}, {"id": 87, "question": "Which SDLC stage produces the Software Requirements Specification (SRS)?", "options": ["Planning", "Requirement Specification", "System Design", "Development"], "answer": 1, "topic": "Planning & requirements", "explanation": "Requirements analysis produces the Software Requirements Specification (SRS), documenting agreed needs and expectations between the customer and development team."}, {"id": 88, "question": "Which document records software requirements?", "options": ["SRS", "DDS", "PDF reader", "IDE"], "answer": 0, "topic": "Planning & requirements", "explanation": "Requirements analysis produces the Software Requirements Specification (SRS), documenting agreed needs and expectations between the customer and development team."}, {"id": 89, "question": "SRS stands for:", "options": ["Software Requirement Specification", "System Resource Software", "Software Runtime System", "System Requirement Source"], "answer": 0, "topic": "Planning & requirements", "explanation": "Requirements analysis produces the Software Requirements Specification (SRS), documenting agreed needs and expectations between the customer and development team."}, {"id": 90, "question": "What does an SRS contain?", "options": ["Software requirements", "Source code", "Test results only", "User passwords"], "answer": 0, "topic": "Planning & requirements", "explanation": "Requirements analysis produces the Software Requirements Specification (SRS), documenting agreed needs and expectations between the customer and development team."}, {"id": 91, "question": "The SRS is a formal agreement between customer and development team. True or false?", "options": ["True", "False", "Only between testers", "Only between managers"], "answer": 0, "topic": "Planning & requirements", "explanation": "Requirements analysis produces the Software Requirements Specification (SRS), documenting agreed needs and expectations between the customer and development team."}, {"id": 92, "question": "Functional requirements describe:", "options": ["What software does", "Software cost", "Team size", "Project duration"], "answer": 0, "topic": "Planning & requirements", "explanation": "Functional requirements say what the system must do, such as transferring funds. Non-functional requirements describe qualities or constraints, such as response time, security and capacity."}, {"id": 93, "question": "Which is a functional requirement?", "options": ["System must be secure", "System supports 1,000 users", "Customer can transfer funds", "System responds quickly"], "answer": 2, "topic": "Planning & requirements", "explanation": "Functional requirements say what the system must do, such as transferring funds. Non-functional requirements describe qualities or constraints, such as response time, security and capacity."}, {"id": 94, "question": "Non-functional requirements describe:", "options": ["System qualities", "Source code", "User names", "Coding steps"], "answer": 0, "topic": "Planning & requirements", "explanation": "Functional requirements say what the system must do, such as transferring funds. Non-functional requirements describe qualities or constraints, such as response time, security and capacity."}, {"id": 95, "question": "Which is a non-functional requirement?", "options": ["User can transfer funds", "Customer can log in", "System responds within two seconds", "User can view account details"], "answer": 2, "topic": "Planning & requirements", "explanation": "Functional requirements say what the system must do, such as transferring funds. Non-functional requirements describe qualities or constraints, such as response time, security and capacity."}, {"id": 96, "question": "A requirement states that a customer must be able to transfer funds between accounts. Another states that the system must respond within two seconds and support a specified number of users. Which classification is correct?", "options": ["Both are functional requirements", "The transfer behaviour is functional; response time and capacity are non-functional", "The transfer behaviour is non-functional; response time is functional", "Both belong only to system design"], "answer": 1, "topic": "Planning & requirements", "explanation": "Functional requirements say what the system must do, such as transferring funds. Non-functional requirements describe qualities or constraints, such as response time, security and capacity."}, {"id": 97, "question": "Requirements gathering collects both functional and non-functional needs. True or false?", "options": ["True", "False", "Only functional", "Only non-functional"], "answer": 0, "topic": "Planning & requirements", "explanation": "Functional requirements say what the system must do, such as transferring funds. Non-functional requirements describe qualities or constraints, such as response time, security and capacity."}, {"id": 98, "question": "Performance, security and scalability are postponed until late in the project. Which common mistake is most directly present?", "options": ["Ignoring non-functional requirements", "Skipping version control", "Using a prototype for feedback", "Applying entry criteria"], "answer": 0, "topic": "Planning & requirements", "explanation": "Performance, security and scalability are non-functional requirements. They need attention early rather than being postponed until the end."}, {"id": 99, "question": "During requirements analysis, two accountants request conflicting report schedules. What should the analyst do according to the described process?", "options": ["Record both contradictory requirements without resolution", "Resolve the ambiguity or inconsistency with the customer and document the agreed requirement in the SRS", "Choose the request from the more senior developer", "Delay all requirements work until system testing"], "answer": 1, "topic": "Planning & requirements", "explanation": "Conflicting requirements must be discussed, reconciled and agreed with stakeholders before they become an approved specification."}, {"id": 100, "question": "What happens during system design?", "options": ["The software structure and design are planned", "The software is marketed", "The system is removed", "Users are charged"], "answer": 0, "topic": "Design & development", "explanation": "High-level design defines overall architecture, major modules and databases. Low-level design defines component logic, APIs, algorithms and data structures."}, {"id": 101, "question": "What does HLD describe?", "options": ["Detailed code logic", "System architecture", "Test cases", "User feedback"], "answer": 1, "topic": "Design & development", "explanation": "High-level design defines overall architecture, major modules and databases. Low-level design defines component logic, APIs, algorithms and data structures."}, {"id": 102, "question": "HLD stands for:", "options": ["High-Level Design", "Hardware Level Data", "High Logic Development", "Hardware Logic Design"], "answer": 0, "topic": "Design & development", "explanation": "High-level design defines overall architecture, major modules and databases. Low-level design defines component logic, APIs, algorithms and data structures."}, {"id": 103, "question": "What does LLD describe?", "options": ["Component-level details", "Project budget", "Business goals only", "System release"], "answer": 0, "topic": "Design & development", "explanation": "High-level design defines overall architecture, major modules and databases. Low-level design defines component logic, APIs, algorithms and data structures."}, {"id": 104, "question": "An architect defines the system architecture, technology stack, database design and major modules. A developer separately specifies a component's logic, APIs and data structures. These activities correspond respectively to:", "options": ["LLD and HLD", "HLD and LLD", "System testing and unit testing", "Requirements validation and deployment"], "answer": 1, "topic": "Design & development", "explanation": "High-level design defines overall architecture, major modules and databases. Low-level design defines component logic, APIs, algorithms and data structures."}, {"id": 105, "question": "What is the output of System Design?", "options": ["SRS", "Feasibility report", "Design Document Specification (DDS)", "Defect report"], "answer": 2, "topic": "Design & development", "explanation": "High-level design defines overall architecture, major modules and databases. Low-level design defines component logic, APIs, algorithms and data structures."}, {"id": 106, "question": "Which statement best distinguishes the traditional and object-oriented design approaches described in the Waterfall design phase?", "options": ["Traditional design identifies objects first; object-oriented design uses only data flow", "Traditional design uses structured analysis followed by structured design; object-oriented design identifies objects and their relationships", "Both approaches avoid deriving architecture from the SRS", "Object-oriented design is the same as unit testing"], "answer": 1, "topic": "Design & development", "explanation": "Traditional design first identifies functions and their data flow. Object-oriented design identifies objects, their attributes and their interactions."}, {"id": 107, "question": "Development mainly means:", "options": ["Coding", "Advertising", "Hiring", "Deployment only"], "answer": 0, "topic": "Design & development", "explanation": "Development turns designs into code and includes code reviews, version control and unit tests. Version control records changes and supports collaboration."}, {"id": 108, "question": "Which SDLC stage involves writing code?", "options": ["Development", "Planning", "Maintenance only", "Deployment only"], "answer": 0, "topic": "Design & development", "explanation": "Development turns designs into code and includes code reviews, version control and unit tests. Version control records changes and supports collaboration."}, {"id": 109, "question": "Which stage includes code reviews and version control?", "options": ["Requirements", "Planning", "Development", "Deployment"], "answer": 2, "topic": "Design & development", "explanation": "Development turns designs into code and includes code reviews, version control and unit tests. Version control records changes and supports collaboration."}, {"id": 110, "question": "Development stage includes coding, code reviews and unit testing. True or false?", "options": ["False", "True", "Only coding", "Only reviews"], "answer": 1, "topic": "Design & development", "explanation": "Development turns designs into code and includes code reviews, version control and unit tests. Version control records changes and supports collaboration."}, {"id": 111, "question": "Version control helps track every change to the code. True or false?", "options": ["False", "True", "Never used", "Only for documents"], "answer": 1, "topic": "Design & development", "explanation": "Development turns designs into code and includes code reviews, version control and unit tests. Version control records changes and supports collaboration."}, {"id": 112, "question": "What is unit testing?", "options": ["Testing individual modules", "Testing the whole system", "Testing user acceptance", "Testing after release"], "answer": 0, "topic": "Testing", "explanation": "Unit testing checks individual functions or modules in isolation."}, {"id": 113, "question": "The testing level performed in isolation on individual modules as code is written is:", "options": ["System Testing", "Unit Testing", "Integration Testing", "Acceptance Testing"], "answer": 1, "topic": "Testing", "explanation": "Unit testing checks individual functions or modules in isolation."}, {"id": 114, "question": "What is integration testing?", "options": ["Testing separate functions only", "Testing combined modules", "Testing project cost", "Testing user needs"], "answer": 1, "topic": "Testing", "explanation": "Integration testing checks how modules work together. Incremental integration makes faults easier to locate than integrating everything at once."}, {"id": 115, "question": "Which testing level checks whether different modules work together?", "options": ["Unit testing", "System testing", "Integration testing", "Acceptance testing"], "answer": 2, "topic": "Testing", "explanation": "Integration testing checks how modules work together. Incremental integration makes faults easier to locate than integrating everything at once."}, {"id": 116, "question": "A set of modules is added in planned steps to a partially integrated system, with testing at each step. What is the main reason for avoiding one-shot integration?", "options": ["It removes the need for system testing", "It allows faults to be isolated and integration to be checked in controlled steps", "It converts integration testing into acceptance testing", "It ensures no module needs unit testing"], "answer": 1, "topic": "Testing", "explanation": "Integration testing checks how modules work together. Incremental integration makes faults easier to locate than integrating everything at once."}, {"id": 117, "question": "What is system testing?", "options": ["Testing the complete system", "Testing one line of code", "Testing one module only", "Testing the project plan"], "answer": 0, "topic": "Testing", "explanation": "System testing checks the complete integrated application against its specified requirements."}, {"id": 118, "question": "What is the purpose of User Acceptance Testing (UAT)?", "options": ["Check code syntax", "Confirm business requirements are met", "Test individual modules only", "Estimate project cost"], "answer": 1, "topic": "Testing", "explanation": "User Acceptance Testing (UAT) asks business users or customers to confirm that the product meets their business requirements."}, {"id": 119, "question": "UAT stands for:", "options": ["User Acceptance Testing", "User Application Tool", "Universal Access Test", "User Analysis Technology"], "answer": 0, "topic": "Testing", "explanation": "User Acceptance Testing (UAT) asks business users or customers to confirm that the product meets their business requirements."}, {"id": 120, "question": "User Acceptance Testing is mainly done by business users or customers. True or false?", "options": ["False", "Only by programmers", "True", "Only by auditors"], "answer": 2, "topic": "Testing", "explanation": "User Acceptance Testing (UAT) asks business users or customers to confirm that the product meets their business requirements."}, {"id": 121, "question": "Business representatives confirm that the delivered software meets their requirements. Which testing level is being described?", "options": ["Unit testing", "Integration testing", "System testing", "User Acceptance Testing"], "answer": 3, "topic": "Testing", "explanation": "User Acceptance Testing (UAT) asks business users or customers to confirm that the product meets their business requirements."}, {"id": 122, "question": "Alpha testing is mainly performed by:", "options": ["Development team", "Random public users", "Customers only", "Hardware vendors"], "answer": 0, "topic": "Testing", "explanation": "In these notes, alpha testing is performed by the development team, beta testing involves selected customers, and acceptance testing is performed by the customer."}, {"id": 123, "question": "Beta testing is performed by:", "options": ["Selected end users", "Only programmers", "Only managers", "Database servers"], "answer": 0, "topic": "Testing", "explanation": "In these notes, alpha testing is performed by the development team, beta testing involves selected customers, and acceptance testing is performed by the customer."}, {"id": 124, "question": "Which testing arrangement is correctly matched?", "options": ["Alpha: selected end users; Beta: development team; Acceptance: support engineers", "Alpha: development team; Beta: friendly selected customers; Acceptance: customer after delivery", "Alpha: customer after delivery; Beta: developers; Acceptance: selected customers before release", "Alpha: operations; Beta: project manager; Acceptance: test engineers"], "answer": 1, "topic": "Testing", "explanation": "In these notes, alpha testing is performed by the development team, beta testing involves selected customers, and acceptance testing is performed by the customer."}, {"id": 125, "question": "Which sequence correctly widens the scope of testing in the seven-stage SDLC?", "options": ["System, then unit, then acceptance, then integration", "Unit, then integration, then system, then user acceptance", "Acceptance, then system, then unit, then integration", "Integration, then acceptance, then unit, then system"], "answer": 1, "topic": "Testing", "explanation": "Testing widens from individual units, to interactions between units, to the complete system, and finally to customer or user acceptance."}, {"id": 126, "question": "What is smoke testing?", "options": ["Basic build checking", "Detailed security testing", "User training", "Software maintenance"], "answer": 0, "topic": "Testing", "explanation": "Smoke testing is a quick check that essential functions work, often after a build or deployment. It is not exhaustive system testing."}, {"id": 127, "question": "A tested release is installed in production, followed by a quick check that essential functions still work. The quick check is:", "options": ["Unit testing", "Smoke testing", "Acceptance planning", "Static verification"], "answer": 1, "topic": "Testing", "explanation": "Smoke testing is a quick check that essential functions work, often after a build or deployment. It is not exhaustive system testing."}, {"id": 128, "question": "Deployment means:", "options": ["Releasing software to users", "Writing requirements", "Designing a database", "Removing software"], "answer": 0, "topic": "Deployment & maintenance", "explanation": "Deployment installs or releases the tested software into the users’ production environment."}, {"id": 129, "question": "Which stage releases software to users?", "options": ["Deployment", "Requirements", "Design", "Planning"], "answer": 0, "topic": "Deployment & maintenance", "explanation": "Deployment installs or releases the tested software into the users’ production environment."}, {"id": 130, "question": "Maintenance mainly includes:", "options": ["Fixing bugs and making updates", "Buying computers", "Writing exams", "Creating hardware"], "answer": 0, "topic": "Deployment & maintenance", "explanation": "Corrective maintenance fixes defects. Perfective maintenance improves features or performance. Adaptive maintenance adjusts software to a changed environment, such as a new operating system."}, {"id": 131, "question": "Which stage handles post-release fixes, updates, and enhancements?", "options": ["Design", "Maintenance", "Planning", "Requirements"], "answer": 1, "topic": "Deployment & maintenance", "explanation": "Corrective maintenance fixes defects. Perfective maintenance improves features or performance. Adaptive maintenance adjusts software to a changed environment, such as a new operating system."}, {"id": 132, "question": "Which maintenance fixes errors?", "options": ["Corrective", "Adaptive", "Perfective", "Preventive"], "answer": 0, "topic": "Deployment & maintenance", "explanation": "Corrective maintenance fixes defects. Perfective maintenance improves features or performance. Adaptive maintenance adjusts software to a changed environment, such as a new operating system."}, {"id": 133, "question": "Porting an existing application to run on a newly released Operating System is:", "options": ["Corrective maintenance", "Adaptive maintenance", "Perfective maintenance", "Prototyping"], "answer": 1, "topic": "Deployment & maintenance", "explanation": "Corrective maintenance fixes defects. Perfective maintenance improves features or performance. Adaptive maintenance adjusts software to a changed environment, such as a new operating system."}, {"id": 134, "question": "Improving system search speed based on customer feature requests is an example of:", "options": ["Perfective maintenance", "Corrective maintenance", "Adaptive maintenance", "Feasibility analysis"], "answer": 0, "topic": "Deployment & maintenance", "explanation": "Corrective maintenance fixes defects. Perfective maintenance improves features or performance. Adaptive maintenance adjusts software to a changed environment, such as a new operating system."}, {"id": 135, "question": "A defect is corrected after release because it was missed during development. A new report is added at the customer's request. The application is then modified to run on a newly released operating system. Which sequence of maintenance types applies?", "options": ["Adaptive, corrective, perfective", "Corrective, perfective, adaptive", "Perfective, adaptive, corrective", "Corrective, adaptive, perfective"], "answer": 1, "topic": "Deployment & maintenance", "explanation": "Corrective maintenance fixes defects. Perfective maintenance improves features or performance. Adaptive maintenance adjusts software to a changed environment, such as a new operating system."}, {"id": 136, "question": "Over the lifetime of a product, maintenance often costs more than original development. True or false?", "options": ["True", "False", "Never", "Only for games"], "answer": 0, "topic": "Deployment & maintenance", "explanation": "Maintenance continues throughout a product’s lifetime. The notes’ approximate 40:60 development-to-maintenance effort split emphasizes budgeting for ongoing support."}, {"id": 137, "question": "The notes state that the relative effort of development to maintenance is roughly 40 to 60. Which implication is most consistent with this statement?", "options": ["Development consumes about 60% and maintenance 40% of the relative effort", "Maintenance can demand a larger share of effort over the product's life, so maintainability deserves design attention", "Maintenance is always cheaper than development", "The ratio means 40 modules are developed and 60 are tested"], "answer": 1, "topic": "Deployment & maintenance", "explanation": "Maintenance continues throughout a product’s lifetime. The notes’ approximate 40:60 development-to-maintenance effort split emphasizes budgeting for ongoing support."}, {"id": 138, "question": "What does DevSecOps include?", "options": ["Security throughout development", "Security after release only", "Coding without testing", "Design without planning"], "answer": 0, "topic": "Deployment & maintenance", "explanation": "DevSecOps integrates security throughout development and operations. CI/CD automates building, testing and releasing software."}, {"id": 139, "question": "A team runs automated security checks in its build and CI/CD pipelines and treats protection as shared work across development, testing and operations. This is most consistent with:", "options": ["Security as a final pre-release activity", "DevSecOps embedding security throughout the SDLC", "Acceptance testing replacing security testing", "A strict waterfall process without feedback"], "answer": 1, "topic": "Deployment & maintenance", "explanation": "DevSecOps integrates security throughout development and operations. CI/CD automates building, testing and releasing software."}, {"id": 140, "question": "CI/CD pipelines automate build, test and release. True or false?", "options": ["False", "True", "Only manual", "Never used"], "answer": 1, "topic": "Deployment & maintenance", "explanation": "DevSecOps integrates security throughout development and operations. CI/CD automates building, testing and releasing software."}, {"id": 141, "question": "Which is a common SDLC mistake?", "options": ["Late testing", "Early feedback", "Clear communication", "Checking requirements"], "answer": 0, "topic": "SDLC pitfalls", "explanation": "A process helps only when it serves real user and business needs. Missing user feedback, rigid execution and treating documents as the end goal can still cause failure."}, {"id": 142, "question": "Treating documentation as the final goal instead of checking with real users is a common mistake. True or false?", "options": ["False", "Only for waterfall", "True", "Never a mistake"], "answer": 2, "topic": "SDLC pitfalls", "explanation": "A process helps only when it serves real user and business needs. Missing user feedback, rigid execution and treating documents as the end goal can still cause failure."}, {"id": 143, "question": "A team produces a complete SRS but never checks its assumptions with actual users. Which common SDLC mistake does this represent?", "options": ["Overengineering early", "Treating documentation as the goal", "Excessive unit testing", "Parallel module development"], "answer": 1, "topic": "SDLC pitfalls", "explanation": "A process helps only when it serves real user and business needs. Missing user feedback, rigid execution and treating documents as the end goal can still cause failure."}, {"id": 144, "question": "A project follows every documented phase, yet the delivered system does not solve the business problem because users were rarely consulted. Which failure reason best explains this?", "options": ["Weak stakeholder involvement", "Too much risk analysis", "Excessive modularity", "Overuse of smoke testing"], "answer": 0, "topic": "SDLC pitfalls", "explanation": "A process helps only when it serves real user and business needs. Missing user feedback, rigid execution and treating documents as the end goal can still cause failure."}, {"id": 145, "question": "A team follows its process mechanically and refuses to adjust when business conditions change. Which failure reason is most directly illustrated?", "options": ["Underestimated complexity", "Rigid execution", "Lack of documentation", "Poor portability"], "answer": 1, "topic": "SDLC pitfalls", "explanation": "A process helps only when it serves real user and business needs. Missing user feedback, rigid execution and treating documents as the end goal can still cause failure."}, {"id": 146, "question": "Why do projects sometimes fail despite following a standard SDLC?", "options": ["Poor requirement clarity and treating SDLC as a rigid checklist", "Excessive team communication", "Early automated unit testing", "Using CI/CD pipelines"], "answer": 0, "topic": "SDLC pitfalls", "explanation": "A process helps only when it serves real user and business needs. Missing user feedback, rigid execution and treating documents as the end goal can still cause failure."}, {"id": 147, "question": "When are defects cheaper to fix?", "options": ["After release", "Early in development", "During maintenance only", "Never"], "answer": 1, "topic": "SDLC pitfalls", "explanation": "Defects are generally cheaper to correct early, before later design, code and tests depend on them."}, {"id": 148, "question": "Which statement about the basic activities across SDLC models is supported by the syllabus?", "options": ["Every model must use exactly seven separately named phases", "Basic activities remain present, although models arrange them differently and may combine or repeat phases", "Only Waterfall includes testing and maintenance", "A model determines the programming language rather than the order of activities"], "answer": 1, "topic": "SDLC pitfalls", "explanation": "SDLC models organize activities differently, but requirements, design, implementation, testing, deployment and maintenance remain core concerns."}, {"id": 149, "question": "A banking application requires account management, fund transfers, security, frontend interfaces, backend services and APIs, followed by functional, performance and security tests. Which interpretation best reflects the syllabus example?", "options": ["Security is considered only after deployment", "The example connects requirements and security planning with design, implementation, testing, deployment and ongoing maintenance", "The example is limited to the coding stage", "The example shows that banking applications do not require maintenance"], "answer": 1, "topic": "SDLC pitfalls", "explanation": "SDLC models organize activities differently, but requirements, design, implementation, testing, deployment and maintenance remain core concerns."}, {"id": 150, "question": "Which model follows a strict sequence?", "options": ["Waterfall", "Spiral", "Incremental", "Prototyping"], "answer": 0, "topic": "Waterfall", "explanation": "Classical Waterfall completes phases in sequence with little provision for feedback. Late defects can force costly rework. It fits stable, well-understood requirements better than changing ones."}, {"id": 151, "question": "What is the main feature of Classical Waterfall?", "options": ["Strict sequential phases", "Parallel development", "Risk analysis each loop", "Continuous prototype feedback"], "answer": 0, "topic": "Waterfall", "explanation": "Classical Waterfall completes phases in sequence with little provision for feedback. Late defects can force costly rework. It fits stable, well-understood requirements better than changing ones."}, {"id": 152, "question": "Can the Classical Waterfall Model easily return to an earlier phase?", "options": ["No, it follows a strict sequence", "Yes, at any time", "Only during deployment", "Only after maintenance"], "answer": 0, "topic": "Waterfall", "explanation": "Classical Waterfall completes phases in sequence with little provision for feedback. Late defects can force costly rework. It fits stable, well-understood requirements better than changing ones."}, {"id": 153, "question": "In classical waterfall, each phase must finish before the next starts. What is the big problem?", "options": ["Late errors cause expensive rework", "Too much fun", "No documentation", "Too many holidays"], "answer": 0, "topic": "Waterfall", "explanation": "Classical Waterfall completes phases in sequence with little provision for feedback. Late defects can force costly rework. It fits stable, well-understood requirements better than changing ones."}, {"id": 154, "question": "Why is the Classical Waterfall Model impractical for real-world complex projects?", "options": ["It lacks documentation steps", "It assumes zero errors occur in early phases and lacks feedback paths", "It requires too many iterations", "It is too flexible to manage"], "answer": 1, "topic": "Waterfall", "explanation": "Classical Waterfall completes phases in sequence with little provision for feedback. Late defects can force costly rework. It fits stable, well-understood requirements better than changing ones."}, {"id": 155, "question": "What is a major limitation of Waterfall?", "options": ["Difficult to handle changes", "No documentation", "No planning", "No testing"], "answer": 0, "topic": "Waterfall", "explanation": "Classical Waterfall completes phases in sequence with little provision for feedback. Late defects can force costly rework. It fits stable, well-understood requirements better than changing ones."}, {"id": 156, "question": "Classical waterfall is mainly a theoretical model from which other models are derived. True or false?", "options": ["False", "True", "Only used today", "Never used"], "answer": 1, "topic": "Waterfall", "explanation": "Classical Waterfall completes phases in sequence with little provision for feedback. Late defects can force costly rework. It fits stable, well-understood requirements better than changing ones."}, {"id": 157, "question": "A design error is discovered during system testing in the Classical Waterfall Model. The affected design, coding and unit-testing work must be repeated. Which shortcoming does this illustrate?", "options": ["The model's lack of sequential phases", "Late discovery of phase errors can force substantial downstream rework", "The model's dependence on user prototypes", "Its inability to produce documentation"], "answer": 1, "topic": "Waterfall", "explanation": "Classical Waterfall completes phases in sequence with little provision for feedback. Late defects can force costly rework. It fits stable, well-understood requirements better than changing ones."}, {"id": 158, "question": "Which model is best suited for a small project with completely stable, well-understood requirements and mandatory compliance docs?", "options": ["Classical / Traditional Waterfall Model", "Prototyping Model", "Spiral Model", "Evolutionary Model"], "answer": 0, "topic": "Waterfall", "explanation": "Classical Waterfall completes phases in sequence with little provision for feedback. Late defects can force costly rework. It fits stable, well-understood requirements better than changing ones."}, {"id": 159, "question": "A project has stable, fully documented requirements, limited expected scope change, and a need for clear milestones and detailed documentation. Which model is the strongest fit?", "options": ["Prototyping", "Classical Waterfall", "Spiral", "RAD"], "answer": 1, "topic": "Waterfall", "explanation": "Classical Waterfall completes phases in sequence with little provision for feedback. Late defects can force costly rework. It fits stable, well-understood requirements better than changing ones."}, {"id": 160, "question": "Iterative Waterfall adds:", "options": ["Feedback paths", "No testing", "No requirements", "No design"], "answer": 0, "topic": "Waterfall", "explanation": "Iterative Waterfall adds feedback paths to earlier phases. Feedback helps correct errors, but the model still does not provide the early partial delivery of Incremental development."}, {"id": 161, "question": "Which model adds feedback paths to Classical Waterfall?", "options": ["Spiral", "Iterative Waterfall", "RAD", "Prototyping"], "answer": 1, "topic": "Waterfall", "explanation": "Iterative Waterfall adds feedback paths to earlier phases. Feedback helps correct errors, but the model still does not provide the early partial delivery of Incremental development."}, {"id": 162, "question": "Which limitation remains in the Iterative Waterfall Model despite its feedback paths?", "options": ["Earlier phases can never be revisited", "It provides no partial or incremental delivery, and phases cannot overlap", "It has no testing phase", "It requires no customer discussion"], "answer": 1, "topic": "Waterfall", "explanation": "Iterative Waterfall adds feedback paths to earlier phases. Feedback helps correct errors, but the model still does not provide the early partial delivery of Incremental development."}, {"id": 163, "question": "Which model connects development and testing stages?", "options": ["V-Model", "Spiral", "Incremental", "Prototyping"], "answer": 0, "topic": "V-Model", "explanation": "The V-Model pairs development activities with testing: business requirements with acceptance tests, system design with system tests, architecture with integration tests, and module design with unit tests."}, {"id": 164, "question": "V-model pairs every development phase with a testing phase. True or false?", "options": ["True", "False", "Only coding", "Only design"], "answer": 0, "topic": "V-Model", "explanation": "The V-Model pairs development activities with testing: business requirements with acceptance tests, system design with system tests, architecture with integration tests, and module design with unit tests."}, {"id": 165, "question": "V-Model mainly focuses on:", "options": ["Testing and validation", "Marketing", "Hardware sales", "Documentation only"], "answer": 0, "topic": "V-Model", "explanation": "The V-Model pairs development activities with testing: business requirements with acceptance tests, system design with system tests, architecture with integration tests, and module design with unit tests."}, {"id": 166, "question": "In the V-model the right side of the V contains matching what?", "options": ["Coding steps", "Marketing steps", "Testing / validation phases", "Lunch breaks"], "answer": 2, "topic": "V-Model", "explanation": "The V-Model pairs development activities with testing: business requirements with acceptance tests, system design with system tests, architecture with integration tests, and module design with unit tests."}, {"id": 167, "question": "Why is the V-Model called the V-Model?", "options": ["Its phases are arranged in a V shape", "It uses five programming languages", "It has no testing stage", "It is shaped like a circle"], "answer": 0, "topic": "V-Model", "explanation": "The V-Model pairs development activities with testing: business requirements with acceptance tests, system design with system tests, architecture with integration tests, and module design with unit tests."}, {"id": 168, "question": "In the V-Model, business requirement analysis matches which testing phase?", "options": ["Unit testing", "Integration testing", "System testing", "User Acceptance Testing"], "answer": 3, "topic": "V-Model", "explanation": "The V-Model pairs development activities with testing: business requirements with acceptance tests, system design with system tests, architecture with integration tests, and module design with unit tests."}, {"id": 169, "question": "In the V-Model, the test plan for User Acceptance Testing is prepared during:", "options": ["Module Design (LLD)", "Business Requirement Analysis", "Code Implementation", "System Maintenance"], "answer": 1, "topic": "V-Model", "explanation": "The V-Model pairs development activities with testing: business requirements with acceptance tests, system design with system tests, architecture with integration tests, and module design with unit tests."}, {"id": 170, "question": "In the V-Model, a test plan is prepared while the corresponding development level is being designed. Which match is correct?", "options": ["Architectural design: unit test cases", "Module design: unit test cases", "Business requirement analysis: system test plan", "System design: acceptance test plan"], "answer": 1, "topic": "V-Model", "explanation": "The V-Model pairs development activities with testing: business requirements with acceptance tests, system design with system tests, architecture with integration tests, and module design with unit tests."}, {"id": 171, "question": "What is verification?", "options": ["Checking work products without executing the code", "Running the final software only", "Selling the software", "Installing hardware"], "answer": 0, "topic": "V-Model", "explanation": "Verification reviews work products without executing software. Validation uses execution and testing to assess whether the product meets the intended requirements."}, {"id": 172, "question": "A review checks requirements and design without executing the software. Later, tests execute the code to assess whether the product meets customer expectations. These are respectively:", "options": ["Validation and verification", "Verification and validation", "Unit testing and static analysis", "Deployment and maintenance"], "answer": 1, "topic": "V-Model", "explanation": "Verification reviews work products without executing software. Validation uses execution and testing to assess whether the product meets the intended requirements."}, {"id": 173, "question": "High-reliability domains such as Healthcare, Aerospace, and Banking best suit which model?", "options": ["Evolutionary Prototyping", "V-Model", "Classical Waterfall", "RAD Model"], "answer": 1, "topic": "V-Model", "explanation": "The V-Model supports clear, stable requirements and early test planning, making it relevant to systems where failures are costly or dangerous."}, {"id": 174, "question": "A project is safety-critical, errors are costly, and requirements are clear and stable. Why might the V-Model be considered?", "options": ["It allows uncontrolled requirement changes in every phase", "It links each development phase to a corresponding test phase and emphasises early verification and validation", "It avoids documentation and formal test planning", "It delivers untested modules continuously"], "answer": 1, "topic": "V-Model", "explanation": "The V-Model supports clear, stable requirements and early test planning, making it relevant to systems where failures are costly or dangerous."}, {"id": 175, "question": "What is the main idea of Incremental Model?", "options": ["Build in small releases", "Build everything at once", "Avoid user feedback", "Skip testing"], "answer": 0, "topic": "Incremental model", "explanation": "Incremental development delivers working portions that add functionality over time. Parallel increments are built simultaneously; staged increments are delivered sequentially. Clear architecture and interfaces are important."}, {"id": 176, "question": "Which model delivers software in small working parts?", "options": ["Incremental Model", "Classical Waterfall", "V-Model", "Spiral Model"], "answer": 0, "topic": "Incremental model", "explanation": "Incremental development delivers working portions that add functionality over time. Parallel increments are built simultaneously; staged increments are delivered sequentially. Clear architecture and interfaces are important."}, {"id": 177, "question": "Incremental model delivers the product in small working portions. Main advantage?", "options": ["Working software appears early", "No testing needed", "Requirements never change", "Only one person works"], "answer": 0, "topic": "Incremental model", "explanation": "Incremental development delivers working portions that add functionality over time. Parallel increments are built simultaneously; staged increments are delivered sequentially. Clear architecture and interfaces are important."}, {"id": 178, "question": "In parallel incremental development:", "options": ["One team builds all modules sequentially", "Different teams build separate modules at the same time", "Testing occurs only after release", "Users build the software"], "answer": 1, "topic": "Incremental model", "explanation": "Incremental development delivers working portions that add functionality over time. Parallel increments are built simultaneously; staged increments are delivered sequentially. Clear architecture and interfaces are important."}, {"id": 179, "question": "Two teams build separate system modules at the same time, then the modules are integrated. Which Incremental Model type is this?", "options": ["Staged delivery", "Parallel development", "Evolutionary prototyping", "Cutover"], "answer": 1, "topic": "Incremental model", "explanation": "Incremental development delivers working portions that add functionality over time. Parallel increments are built simultaneously; staged increments are delivered sequentially. Clear architecture and interfaces are important."}, {"id": 180, "question": "A project releases a working subsystem at planned intervals, one stage after another. This is best described as:", "options": ["Parallel development", "Staged delivery", "Rapid throwaway prototyping", "Risk analysis"], "answer": 1, "topic": "Incremental model", "explanation": "Incremental development delivers working portions that add functionality over time. Parallel increments are built simultaneously; staged increments are delivered sequentially. Clear architecture and interfaces are important."}, {"id": 181, "question": "Which condition is a notable disadvantage of the Incremental Process Model?", "options": ["It cannot deliver working software early", "Repeated testing and integration may increase cost, and integration can be challenging", "It forbids changes between increments", "It requires all requirements to remain unknown"], "answer": 1, "topic": "Incremental model", "explanation": "Incremental development delivers working portions that add functionality over time. Parallel increments are built simultaneously; staged increments are delivered sequentially. Clear architecture and interfaces are important."}, {"id": 182, "question": "What is a prototype?", "options": ["An early working version", "Final software", "A test report", "A project budget"], "answer": 0, "topic": "Prototyping", "explanation": "A prototype is an early working model used to clarify requirements through user feedback. It is useful when customers cannot yet describe their needs precisely."}, {"id": 183, "question": "What is the main purpose of a prototype?", "options": ["Replace all testing", "Collect early user feedback", "Complete maintenance", "Avoid requirements"], "answer": 1, "topic": "Prototyping", "explanation": "A prototype is an early working model used to clarify requirements through user feedback. It is useful when customers cannot yet describe their needs precisely."}, {"id": 184, "question": "Which model suits unclear requirements and early user feedback?", "options": ["Classical Waterfall", "Prototyping", "V-Model", "Incremental"], "answer": 1, "topic": "Prototyping", "explanation": "A prototype is an early working model used to clarify requirements through user feedback. It is useful when customers cannot yet describe their needs precisely."}, {"id": 185, "question": "A customer cannot clearly describe the required interface. Developers create an early working model, obtain user feedback, and refine it repeatedly before building the final system. Which model fits best?", "options": ["Classical Waterfall", "Prototyping", "V-Model", "Iterative Waterfall"], "answer": 1, "topic": "Prototyping", "explanation": "A prototype is an early working model used to clarify requirements through user feedback. It is useful when customers cannot yet describe their needs precisely."}, {"id": 186, "question": "Which prototype type is not necessarily part of the final product?", "options": ["Evolutionary", "Rapid throwaway", "Incremental", "Extreme"], "answer": 1, "topic": "Prototyping", "explanation": "Throwaway prototypes are discarded after learning from feedback. Evolutionary prototypes are refined into the final system."}, {"id": 187, "question": "How does Rapid Throwaway Prototyping differ from Evolutionary Prototyping?", "options": ["Throwaway prototypes are discarded after requirements are clarified; evolutionary prototypes are refined into the final product", "Evolutionary prototypes are discarded immediately after 1 day", "Throwaway prototypes require full database connections", "There is no difference between them"], "answer": 0, "topic": "Prototyping", "explanation": "Throwaway prototypes are discarded after learning from feedback. Evolutionary prototypes are refined into the final system."}, {"id": 188, "question": "Throwaway prototyping means the prototype is discarded after feedback. True or false?", "options": ["True", "False", "It becomes the final system", "No feedback is taken"], "answer": 0, "topic": "Prototyping", "explanation": "Throwaway prototypes are discarded after learning from feedback. Evolutionary prototypes are refined into the final system."}, {"id": 189, "question": "A first prototype is repeatedly improved until it becomes the accepted system. Which type is described?", "options": ["Rapid throwaway", "Evolutionary", "Parallel", "Staged delivery"], "answer": 1, "topic": "Prototyping", "explanation": "An evolutionary prototype is repeatedly improved until it becomes the accepted final product."}, {"id": 190, "question": "Extreme Prototyping is a 3-phase approach used primarily for:", "options": ["Embedded vehicle braking systems", "Web application development", "Mainframe hardware design", "Database migration"], "answer": 1, "topic": "Prototyping", "explanation": "Extreme Prototyping is used for web applications: static pages first, simulated functionality next, and integration with real services last."}, {"id": 191, "question": "A web project first presents static HTML pages, then functional screens using simulated data, and finally connects real services. This sequence identifies:", "options": ["Incremental delivery", "Extreme prototyping", "Classical Waterfall", "Spiral risk analysis"], "answer": 1, "topic": "Prototyping", "explanation": "Extreme Prototyping is used for web applications: static pages first, simulated functionality next, and integration with real services last."}, {"id": 192, "question": "Several prototype pieces are built separately and later merged. The notes warn that integration problems may occur if interfaces and overall architecture are not planned. Which type is this?", "options": ["Extreme prototyping", "Incremental prototyping", "Evolutionary prototyping", "Rapid throwaway prototyping"], "answer": 1, "topic": "Prototyping", "explanation": "Incremental prototyping builds separate prototype pieces and merges them. Poorly planned interfaces or architecture can create integration problems."}, {"id": 193, "question": "Which risk is specifically associated with allowing prototype iterations to dominate the project?", "options": ["The final product may be delayed or the prototype may create a false sense of completion", "The project cannot receive user feedback", "The system must be released after the first prototype", "The requirements become permanently fixed"], "answer": 0, "topic": "Prototyping", "explanation": "Repeated prototype changes can expand scope and consume time. Iterations need clear goals and limits."}, {"id": 194, "question": "What is the main focus of Spiral Model?", "options": ["Risk analysis", "Fast coding only", "No user feedback", "No planning"], "answer": 0, "topic": "Spiral model", "explanation": "The Spiral Model emphasizes identifying and reducing risks through repeated development loops, using prototypes when needed. Q197 in this practice bank identifies risk analysis as the key starting activity."}, {"id": 195, "question": "Which model is mainly driven by risk analysis?", "options": ["Classical Waterfall", "Spiral Model", "V-Model", "RAD Model"], "answer": 1, "topic": "Spiral model", "explanation": "The Spiral Model emphasizes identifying and reducing risks through repeated development loops, using prototypes when needed. Q197 in this practice bank identifies risk analysis as the key starting activity."}, {"id": 196, "question": "A project is large, complex and uncertain. Every development loop begins by identifying and analysing risks, and prototypes are used to reduce them. Which model is most appropriate?", "options": ["RAD", "Spiral", "Classical Waterfall", "V-Model"], "answer": 1, "topic": "Spiral model", "explanation": "The Spiral Model emphasizes identifying and reducing risks through repeated development loops, using prototypes when needed. Q197 in this practice bank identifies risk analysis as the key starting activity."}, {"id": 197, "question": "Each loop of the spiral model begins with what activity?", "options": ["Full deployment", "Writing the manual", "Risk analysis", "Party"], "answer": 2, "topic": "Spiral model", "explanation": "The Spiral Model emphasizes identifying and reducing risks through repeated development loops, using prototypes when needed. Q197 in this practice bank identifies risk analysis as the key starting activity."}, {"id": 198, "question": "Which Spiral quadrant identifies risks and may build prototypes to reduce them?", "options": ["Objective setting", "Risk analysis", "Development and testing", "Review and planning"], "answer": 1, "topic": "Spiral model", "explanation": "The Spiral Model emphasizes identifying and reducing risks through repeated development loops, using prototypes when needed. Q197 in this practice bank identifies risk analysis as the key starting activity."}, {"id": 199, "question": "What are the four quadrants executed in every spiral loop of the Spiral Model?", "options": ["Planning, Coding, Debugging, Sales", "Objective Setting, Risk Analysis, Development & Testing, Review & Planning", "Feasibility, Documentation, Maintenance, Support", "Unit Test, Integration Test, System Test, UAT"], "answer": 1, "topic": "Spiral model", "explanation": "The bank describes four Spiral activities: planning objectives and alternatives, risk analysis, development and testing, and customer evaluation or planning the next loop."}, {"id": 200, "question": "In a Spiral loop, the customer evaluates the current version and feedback is used to plan the next loop. Which quadrant is this?", "options": ["Objective setting", "Risk analysis", "Development and testing", "Review and planning"], "answer": 3, "topic": "Spiral model", "explanation": "The bank describes four Spiral activities: planning objectives and alternatives, risk analysis, development and testing, and customer evaluation or planning the next loop."}, {"id": 201, "question": "Why is the Spiral Model described as a meta-model in the notes?", "options": ["It is a fixed sequence that replaces all other models", "It can combine elements of Waterfall, Iterative and Prototyping approaches according to project risks", "It is used only for web interfaces", "It contains no development or testing activities"], "answer": 1, "topic": "Spiral model", "explanation": "Spiral is called a meta-model because it combines ideas such as systematic development and prototyping within a risk-driven framework."}, {"id": 202, "question": "Which model is called a meta-model combining ideas from other models?", "options": ["Spiral", "V-Model", "Classical Waterfall", "RAD"], "answer": 0, "topic": "Spiral model", "explanation": "Spiral is called a meta-model because it combines ideas such as systematic development and prototyping within a risk-driven framework."}, {"id": 203, "question": "In the Spiral Model, what does the radius represent?", "options": ["Developer count", "Cost of project so far", "Number of requirements", "Testing time"], "answer": 1, "topic": "Spiral model", "explanation": "The radius of the spiral represents cumulative cost or effort spent so far, rather than team size or code length."}, {"id": 204, "question": "Spiral model is especially useful for large, high-risk projects. True or false?", "options": ["True", "False", "Only for tiny apps", "Only for websites"], "answer": 0, "topic": "Spiral model", "explanation": "Spiral is useful for large, high-risk projects, but its risk analysis and management overhead can be excessive for small, low-risk work."}, {"id": 205, "question": "Which statement is the strongest reason the Spiral Model may be unsuitable for a small, low-risk project?", "options": ["It cannot accommodate changing requirements", "Its repeated loops and continuous risk analysis can make it costly and complex to manage", "It does not allow prototypes", "It releases only once at the end"], "answer": 1, "topic": "Spiral model", "explanation": "Spiral is useful for large, high-risk projects, but its risk analysis and management overhead can be excessive for small, low-risk work."}, {"id": 206, "question": "What does RAD stand for?", "options": ["Rapid Application Development", "Random Application Design", "Reliable Access Data", "Rapid Analysis Device"], "answer": 0, "topic": "RAD", "explanation": "Rapid Application Development (RAD) uses short development cycles, prototyping, reusable components and continuous user feedback. These notes describe cycles of about 60 to 90 days."}, {"id": 207, "question": "Which model emphasizes rapid prototyping, short cycles, and user feedback?", "options": ["RAD", "Classical Waterfall", "V-Model", "Iterative Waterfall"], "answer": 0, "topic": "RAD", "explanation": "Rapid Application Development (RAD) uses short development cycles, prototyping, reusable components and continuous user feedback. These notes describe cycles of about 60 to 90 days."}, {"id": 208, "question": "Which SDLC model relies heavily on low-code platforms, reusable components, and active user involvement?", "options": ["Classical Waterfall", "RAD Model", "V-Model", "Cleanroom Model"], "answer": 1, "topic": "RAD", "explanation": "Rapid Application Development (RAD) uses short development cycles, prototyping, reusable components and continuous user feedback. These notes describe cycles of about 60 to 90 days."}, {"id": 209, "question": "What is the typical development cycle timeframe for a Rapid Application Development (RAD) project?", "options": ["5 to 10 days", "60 to 90 days", "12 to 18 months", "3 years"], "answer": 1, "topic": "RAD", "explanation": "Rapid Application Development (RAD) uses short development cycles, prototyping, reusable components and continuous user feedback. These notes describe cycles of about 60 to 90 days."}, {"id": 210, "question": "A team must deliver a modular application quickly, uses short cycles of about 60 to 90 days, develops modules in parallel, and receives continuous user feedback. Which model is indicated?", "options": ["RAD", "V-Model", "Classical Waterfall", "Iterative Waterfall"], "answer": 0, "topic": "RAD", "explanation": "Rapid Application Development (RAD) uses short development cycles, prototyping, reusable components and continuous user feedback. These notes describe cycles of about 60 to 90 days."}, {"id": 211, "question": "Which sequence gives the four RAD phases in the order stated in the syllabus?", "options": ["User design, then requirements planning, then cutover, then construction", "Requirements planning, then user design, then construction, then cutover", "Planning, then risk analysis, then implementation, then review", "Feasibility, then SRS, then unit testing, then maintenance"], "answer": 1, "topic": "RAD", "explanation": "The RAD phases are requirements planning, user design, construction and cutover. Cutover includes integration, testing, user acceptance and deployment."}, {"id": 212, "question": "What happens during RAD Cutover?", "options": ["Requirements are first gathered", "Initial prototype is made", "Modules are integrated, tested, and deployed", "Feasibility is evaluated"], "answer": 2, "topic": "RAD", "explanation": "The RAD phases are requirements planning, user design, construction and cutover. Cutover includes integration, testing, user acceptance and deployment."}, {"id": 213, "question": "In RAD, modules are integrated, the system is tested including UAT, and the final system is deployed. This occurs in:", "options": ["Requirements planning", "User design", "Construction", "Cutover"], "answer": 3, "topic": "RAD", "explanation": "The RAD phases are requirements planning, user design, construction and cutover. Cutover includes integration, testing, user acceptance and deployment."}, {"id": 214, "question": "Which condition would most strongly undermine the suitability of RAD?", "options": ["Users are available for regular feedback", "The application can be modularised", "The team lacks reusable components and the system cannot be divided into modules", "The delivery deadline is short"], "answer": 2, "topic": "RAD", "explanation": "RAD depends on a system that can be modularized, skilled developers and continuous customer involvement. A short deadline alone does not make RAD suitable."}, {"id": 215, "question": "A known disadvantage of RAD is that it needs skilled people and continuous user involvement. True or false?", "options": ["True", "False", "Needs no users", "Needs no skill"], "answer": 0, "topic": "RAD", "explanation": "RAD depends on a system that can be modularized, skilled developers and continuous customer involvement. A short deadline alone does not make RAD suitable."}, {"id": 216, "question": "A manager chooses RAD solely because the project is urgent, but users cannot participate regularly and the system cannot be divided into modules. What is the best evaluation?", "options": ["The choice is still ideal because RAD requires only a short deadline", "The choice conflicts with key RAD conditions: modularisation and continuous customer involvement", "The project should automatically use the Spiral Model", "RAD is appropriate only when requirements are unknown"], "answer": 1, "topic": "RAD", "explanation": "RAD depends on a system that can be modularized, skilled developers and continuous customer involvement. A short deadline alone does not make RAD suitable."}, {"id": 217, "question": "A comparison question asks which model accepts changes even at later stages and delivers a new version in every loop. Which model matches both properties?", "options": ["Iterative Waterfall", "Spiral", "V-Model", "Classical Waterfall"], "answer": 1, "topic": "Model comparisons", "explanation": "Spiral uses repeated risk-driven loops and produces an evolving version at each cycle, allowing requirements to be reconsidered."}, {"id": 218, "question": "Which comparison is accurate?", "options": ["Classical Waterfall: partial delivery; Incremental: single final delivery", "Iterative Waterfall: feedback to earlier phases but no partial delivery; Incremental: working portions delivered early", "V-Model: unpaired testing; Prototyping: no user evaluation", "RAD: fixed sequential phases; Spiral: no risk analysis"], "answer": 1, "topic": "Model comparisons", "explanation": "Iterative Waterfall adds feedback between phases. Incremental development additionally delivers usable portions early."}, {"id": 219, "question": "A project has unclear and changing requirements, so the customer needs to inspect early versions and refine expectations. Another project has high uncertainty and substantial technical risk. Which pairing is most defensible?", "options": ["Waterfall for the first; V-Model for the second", "Prototyping for the first; Spiral for the second", "RAD for the first; Classical Waterfall for the second", "V-Model for the first; Incremental for the second"], "answer": 1, "topic": "Model comparisons", "explanation": "Prototyping clarifies unclear requirements through early user feedback. Spiral explicitly addresses substantial uncertainty and technical risks."}, {"id": 220, "question": "Which statement correctly distinguishes Incremental delivery from Prototyping?", "options": ["Incremental releases successive working portions that add functionality; prototyping refines an early model using user feedback before the final product", "Incremental never tests existing features; prototyping always releases production software after each iteration", "Both models require all requirements to be fixed before any user interaction", "Prototyping is defined by parallel teams, while Incremental is defined by risk quadrants"], "answer": 0, "topic": "Model comparisons", "explanation": "Incremental delivery releases successive working portions. Prototyping uses early models to discover and refine requirements; a prototype need not be production software."}, {"id": 221, "question": "A team has clear requirements but is learning unfamiliar technology, expects possible changes, and values early error correction. The notes list this as a possible use case for:", "options": ["Iterative Waterfall", "Classical Waterfall only", "RAD only", "Rapid throwaway prototyping only"], "answer": 0, "topic": "Model comparisons", "explanation": "The notes list Iterative Waterfall for manageable phases, regular feedback and earlier error correction, including cases involving unfamiliar technology or limited resources."}, {"id": 222, "question": "A project team has limited resources and wants a large project divided into manageable phases, with regular feedback to correct errors. Which model's stated use cases best fit?", "options": ["Iterative Waterfall", "V-Model", "Extreme prototyping", "RAD"], "answer": 0, "topic": "Model comparisons", "explanation": "The notes list Iterative Waterfall for manageable phases, regular feedback and earlier error correction, including cases involving unfamiliar technology or limited resources."}];
